INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('1688e78a-baaf-4bb7-8a99-29fcd0abf2fe', '21feff02-016d-46e2-bb9d-c27495133b1b', '110. óra: Testek térfogata', 'Téglatest és kocka térfogatának (V) kiszámítása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "29b96f3b-948f-46b1-b2af-d81675fff8db", "text": "Mi a kocka térfogatának képlete (''a'' éllel)?", "type": "multiple-choice", "options": [{"id": "2248d16f-a865-495b-934c-4aa0d55093fd", "text": "V = a * a * a (a³)", "isCorrect": true}, {"id": "6a607fe3-70e5-4b13-a7d2-5013567d2ed9", "text": "V = 6 * a²", "isCorrect": false}, {"id": "052d11fb-b1e0-4280-835e-3a8ed6367897", "text": "V = 12 * a", "isCorrect": false}, {"id": "5dc4ce5b-218a-4fde-99b2-bafd7d8d81bb", "text": "V = a + a + a", "isCorrect": false}], "timeLimit": 15}, {"id": "006594b7-a6c1-491a-bc3e-7b2337689242", "text": "Mi a téglatest térfogatának képlete (a, b, c élekkel)?", "type": "multiple-choice", "options": [{"id": "1a5251e1-cc6b-4f81-b4ce-d0cc60123f14", "text": "V = a * b * c", "isCorrect": true}, {"id": "39bb924b-e76a-4c9a-991e-05b7f2ff41a7", "text": "V = 2 * (a+b+c)", "isCorrect": false}, {"id": "f8269281-4d42-4f2f-b34c-6caa86ee756d", "text": "V = a * b", "isCorrect": false}, {"id": "57183d16-b92e-4714-86b0-684741a6bdef", "text": "V = a + b + c", "isCorrect": false}], "timeLimit": 15}, {"id": "cb2aef17-4edd-4c89-9099-e817bf939d00", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "414a69a6-e76e-456e-ab21-d6d4fbe089b4", "text": "Mennyi a 2 cm, 4 cm, 5 cm élű téglatest térfogata? (2 * 4 * 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "2e75d39b-4cee-4810-a85f-ccb0de7e9df4", "text": "A térfogatot mindig köbmértékegységben (cm³, m³, dm³) vagy űrmértékben (liter, dl) adjuk meg.", "type": "true-false", "options": [{"id": "4f6cf4d5-8fbb-4b9d-95e5-15260bdfdbbe", "text": "Igaz", "isCorrect": true}, {"id": "c3fd04e5-60ec-4e6d-a2bb-b2d7f07f7725", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "221fabae-d467-4bd8-b0a3-4341a42efea2", "text": "Mennyi a 4 cm élű kocka térfogata? (4 * 4 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "6a68683c-b1a0-4692-8827-f090bfa85b7c", "text": "Mennyi a 10 cm élű kocka térfogata cm³-ben? (1000 cm³ = 1 liter)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW()),
('d794f854-0e93-48c0-9abd-d7041e7a9197', '21feff02-016d-46e2-bb9d-c27495133b1b', '111. óra: Projektóra', 'Épülettervezés I. - Vetületi képek megrajzolása, makett alaprajzának elkészítése.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "8a227e32-b218-436d-9c91-03ffdb65b6be", "text": "Mit mutat meg egy épület felülnézete (alaprajza)?", "type": "multiple-choice", "options": [{"id": "f391911e-45cf-4674-94a6-a05e595bb321", "text": "Az épület felülről látható elrendezését és méreteit", "isCorrect": true}, {"id": "79b12a1e-3f13-4099-a703-85a828a2927b", "text": "A tető színét", "isCorrect": false}, {"id": "8fe111f6-c227-489b-9632-8c99274d1815", "text": "Az épület magasságát", "isCorrect": false}, {"id": "5f7c2abf-698e-4a14-b9e8-7734deb2921d", "text": "Az ablakok mintáját", "isCorrect": false}], "timeLimit": 15}, {"id": "395ebbe3-4336-4f1d-81ba-2d1bbbc20729", "text": "Egy épület makettjének elkészítése segít a térbeli arányok megértésében.", "type": "true-false", "options": [{"id": "3d14b340-42e7-4c52-b40a-776e79e6916a", "text": "Igaz", "isCorrect": true}, {"id": "c81b4f5f-1165-4217-9fb2-b69f7d3ec68f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e2a88f91-1578-4c35-bc5c-a5adaf9e8765", "text": "Hány m² az 5 m x 6 m-es alaprajzú házalap területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "1a1e2192-21ac-4b0a-9708-52b322c1f156", "text": "A méretarányos rajz készítése elengedhetetlen az építészetben.", "type": "true-false", "options": [{"id": "93f8a437-a97e-4276-83ec-e54ec3dc2e7c", "text": "Igaz", "isCorrect": true}, {"id": "fd2c66f5-8a2d-4bbe-86e8-e5345df0a533", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5da3fc70-6054-4026-ac9c-7a1146da701e", "text": "Ha az 1:100 méretarányú rajzon a fal 5 cm, hány méter a valóságban? (5 * 100 cm)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "be2a697f-c3a4-404a-b055-8f79284a7c20", "text": "A csoportszervezés és munkamegosztás felgyorsítja a projekt elvégzését.", "type": "true-false", "options": [{"id": "4a439b5e-45bf-4114-8e39-a5f714d280d7", "text": "Igaz", "isCorrect": true}, {"id": "b459178d-1205-4a8b-9f8a-b5222319a683", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "26376776-9aed-4d2b-8eb1-edd67fb43204", "text": "Hány oldallapja van a téglatest alakú épületnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW()),
('56adc90d-c9b9-49fc-865c-c9cc2d3e0974', '21feff02-016d-46e2-bb9d-c27495133b1b', '112. óra: Projektóra II.', 'Épülettervezés II. - Makett megépítése kartonból, legóból, egységkockákból.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "4f051eb9-5f1f-431f-91b1-1e9469ce10c1", "text": "Hány darab 1 cm³-es kiskockára van szükség egy 3 cm x 4 cm x 5 cm-es épületmakett megépítéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "d19bc374-d3e6-44d5-8f73-a20434a55241", "text": "Az épületmakett térfogata megegyezik a felhasznált egységkockák térfogatának összegevel.", "type": "true-false", "options": [{"id": "be3fd902-e4ee-4b3f-9108-26edd8f6e3fe", "text": "Igaz", "isCorrect": true}, {"id": "da8e99cf-e332-402e-a7c3-5ef5b4f6f8fa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0e553b94-2da4-423d-8629-f8eabcbcff9d", "text": "Melyik testből építhető fel a legkönnyebben téglatest alakú ház?", "type": "multiple-choice", "options": [{"id": "cc9665f7-cd20-450c-bc12-93749d1ed47e", "text": "Egységkockákból / kartondobozból", "isCorrect": true}, {"id": "82f5d3c3-3fbf-4a1a-a42b-c0c0ec712f21", "text": "Gömbökből", "isCorrect": false}, {"id": "94a3be85-f914-4cd8-9286-831242643220", "text": "Kúpokból", "isCorrect": false}, {"id": "eaa7b936-5066-4de8-8676-d28aba5fc3b8", "text": "Hengerekből", "isCorrect": false}], "timeLimit": 15}, {"id": "d0cc61f8-eb61-4f70-89c8-19414db48ee5", "text": "A makett készítése során a stabil szerkezet kialakítása a cél.", "type": "true-false", "options": [{"id": "7c668dfe-415a-4c2c-90be-f781c7694b61", "text": "Igaz", "isCorrect": true}, {"id": "569160e5-8145-474d-a624-bae5852d372a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "04130849-6d14-41ba-9421-06f2e3c06811", "text": "Mennyi a 2 cm élű kockákból álló 2x2x2-es házikó térfogata? (8 * 8 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "76991123-5df9-4931-80e4-